create table public.restaurants(id uuid primary key default gen_random_uuid(),slug text unique not null check(slug ~ '^[a-z0-9-]+$'),name text not null,active boolean not null default false,delivery_fee_cents integer not null default 0 check(delivery_fee_cents>=0),created_at timestamptz not null default now());
create table public.restaurant_members(restaurant_id uuid references public.restaurants on delete cascade,user_id uuid references auth.users on delete cascade,role text not null check(role in ('owner','staff')),primary key(restaurant_id,user_id));
create table public.categories(id uuid primary key default gen_random_uuid(),restaurant_id uuid not null references public.restaurants,name text not null,active boolean not null default true,unique(restaurant_id,id));
create table public.products(id uuid primary key default gen_random_uuid(),restaurant_id uuid not null references public.restaurants,category_id uuid not null,name text not null,description text not null default '',price_cents integer not null check(price_cents>0),active boolean not null default true,foreign key(restaurant_id,category_id) references public.categories(restaurant_id,id),unique(restaurant_id,id));
create table public.orders(id uuid primary key default gen_random_uuid(),restaurant_id uuid not null references public.restaurants,customer_name text not null,customer_phone text not null,delivery_address text not null,status text not null default 'new' check(status in ('new','confirmed','preparing','delivering','delivered','cancelled')),total_cents integer not null check(total_cents>0),delivery_fee_cents integer not null default 0 check(delivery_fee_cents>=0),whatsapp_consent boolean not null default false,created_at timestamptz not null default now(),unique(restaurant_id,id));
create table public.order_items(id uuid primary key default gen_random_uuid(),restaurant_id uuid not null,order_id uuid not null,product_id uuid not null,product_name text not null,quantity integer not null check(quantity between 1 and 99),unit_price_cents integer not null check(unit_price_cents>0),foreign key(restaurant_id,order_id) references public.orders(restaurant_id,id),foreign key(restaurant_id,product_id) references public.products(restaurant_id,id));
create table public.payments(id uuid primary key default gen_random_uuid(),restaurant_id uuid not null,order_id uuid not null,method text not null check(method in ('pix','card')),status text not null default 'pending' check(status in ('pending','paid','failed','refunded')),amount_cents integer not null check(amount_cents>0),provider text,provider_id text,unique(provider,provider_id),foreign key(restaurant_id,order_id) references public.orders(restaurant_id,id));
create table public.notifications(id uuid primary key default gen_random_uuid(),restaurant_id uuid not null,order_id uuid not null,event text not null,status text not null default 'pending' check(status in ('pending','sent','failed')),created_at timestamptz not null default now(),foreign key(restaurant_id,order_id) references public.orders(restaurant_id,id),unique(order_id,event));
create table public.subscriptions(id uuid primary key default gen_random_uuid(),restaurant_id uuid unique not null references public.restaurants,plan text not null default 'trial',status text not null default 'trial' check(status in ('trial','active','past_due','cancelled')),expires_at timestamptz);
create index on public.restaurant_members(user_id);create index on public.categories(restaurant_id);create index on public.products(restaurant_id,category_id);create index on public.orders(restaurant_id,created_at);create index on public.order_items(restaurant_id,order_id);create index on public.order_items(restaurant_id,product_id);create index on public.payments(restaurant_id,order_id);create index on public.notifications(restaurant_id,order_id);
alter table public.restaurants enable row level security; revoke all on public.restaurants from anon,authenticated; grant all on public.restaurants to service_role;
alter table public.restaurant_members enable row level security; revoke all on public.restaurant_members from anon,authenticated; grant all on public.restaurant_members to service_role;
alter table public.categories enable row level security; revoke all on public.categories from anon,authenticated; grant all on public.categories to service_role;
alter table public.products enable row level security; revoke all on public.products from anon,authenticated; grant all on public.products to service_role;
alter table public.orders enable row level security; revoke all on public.orders from anon,authenticated; grant all on public.orders to service_role;
alter table public.order_items enable row level security; revoke all on public.order_items from anon,authenticated; grant all on public.order_items to service_role;
alter table public.payments enable row level security; revoke all on public.payments from anon,authenticated; grant all on public.payments to service_role;
alter table public.notifications enable row level security; revoke all on public.notifications from anon,authenticated; grant all on public.notifications to service_role;
alter table public.subscriptions enable row level security; revoke all on public.subscriptions from anon,authenticated; grant all on public.subscriptions to service_role;
grant select on public.restaurants,public.categories,public.products to anon,authenticated;
grant select on public.restaurant_members,public.orders,public.order_items,public.payments,public.notifications,public.subscriptions to authenticated;
create policy own_membership on public.restaurant_members for select to authenticated using(user_id=(select auth.uid()));
create policy visible_restaurant on public.restaurants for select to anon,authenticated using(active);
create policy member_restaurant on public.restaurants for select to authenticated using(exists(select 1 from public.restaurant_members m where m.restaurant_id=restaurants.id and m.user_id=(select auth.uid())));
create policy public_menu on public.categories for select to anon,authenticated using(active and exists(select 1 from public.restaurants r where r.id=categories.restaurant_id and r.active));
create policy public_menu on public.products for select to anon,authenticated using(active and exists(select 1 from public.restaurants r where r.id=products.restaurant_id and r.active) and exists(select 1 from public.categories c where c.id=products.category_id and c.active));
create policy member_read on public.categories for select to authenticated using(exists(select 1 from public.restaurant_members m where m.restaurant_id=categories.restaurant_id and m.user_id=(select auth.uid())));
create policy member_read on public.products for select to authenticated using(exists(select 1 from public.restaurant_members m where m.restaurant_id=products.restaurant_id and m.user_id=(select auth.uid())));
create policy member_read on public.orders for select to authenticated using(exists(select 1 from public.restaurant_members m where m.restaurant_id=orders.restaurant_id and m.user_id=(select auth.uid())));
create policy member_read on public.order_items for select to authenticated using(exists(select 1 from public.restaurant_members m where m.restaurant_id=order_items.restaurant_id and m.user_id=(select auth.uid())));
create policy member_read on public.payments for select to authenticated using(exists(select 1 from public.restaurant_members m where m.restaurant_id=payments.restaurant_id and m.user_id=(select auth.uid())));
create policy member_read on public.notifications for select to authenticated using(exists(select 1 from public.restaurant_members m where m.restaurant_id=notifications.restaurant_id and m.user_id=(select auth.uid())));
create policy member_read on public.subscriptions for select to authenticated using(exists(select 1 from public.restaurant_members m where m.restaurant_id=subscriptions.restaurant_id and m.user_id=(select auth.uid())));
